import{_ as t,o as e,c as s,a2 as n}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"低代码平台：Dify 与 Coze","description":"用可视化编排搭建 Agent 和工作流：Dify 与 Coze 的能力对比、典型用法，以及什么时候该从低代码转向写代码。","frontmatter":{"title":"低代码平台：Dify 与 Coze","description":"用可视化编排搭建 Agent 和工作流：Dify 与 Coze 的能力对比、典型用法，以及什么时候该从低代码转向写代码。"},"headers":[],"relativePath":"guide/11-frameworks/low-code.md","filePath":"guide/11-frameworks/low-code.md","lastUpdated":null}'),l={name:"guide/11-frameworks/low-code.md"};function i(r,a,o,d,p,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="低代码平台-dify-与-coze" tabindex="-1">低代码平台：Dify 与 Coze <a class="header-anchor" href="#低代码平台-dify-与-coze" aria-label="Permalink to &quot;低代码平台：Dify 与 Coze&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>了解低代码 Agent 平台提供了哪些能力，和代码框架是什么关系</li><li>对比 Dify 与 Coze 的定位、部署方式和适用场景</li><li>掌握&quot;低代码搭原型 + API 集成到业务系统&quot;的常见用法</li><li>判断一个需求该用低代码还是写代码，以及何时迁移</li></ul></div><p>本文是概念与选型文章，不包含代码。平台功能更新很快，具体功能以官方文档为准。</p><h2 id="低代码平台在做什么" tabindex="-1">低代码平台在做什么 <a class="header-anchor" href="#低代码平台在做什么" aria-label="Permalink to &quot;低代码平台在做什么&quot;">​</a></h2><p>回顾前面的模块：调用模型、写提示词、定义工具、做 RAG、编排流程、管理会话。低代码平台把这些能力做成了可视化的积木：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────── 低代码 Agent 平台 ─────────────────────────┐</span></span>
<span class="line"><span>│                                                                    │</span></span>
<span class="line"><span>│  模型接入      提示词编辑      知识库（RAG）     插件 / 工具           │</span></span>
<span class="line"><span>│  (多厂商切换)  (变量、调试)    (上传文档即可)    (HTTP API、MCP 等)     │</span></span>
<span class="line"><span>│                                                                    │</span></span>
<span class="line"><span>│  ┌─────────── 可视化工作流画布 ───────────┐                          │</span></span>
<span class="line"><span>│  │ 开始 → LLM → 条件分支 → 工具 → 代码 → 结束 │                       │</span></span>
<span class="line"><span>│  └────────────────────────────────────────┘                        │</span></span>
<span class="line"><span>│                                                                    │</span></span>
<span class="line"><span>│  发布：Web 应用 / API / 嵌入网页 / 接入 IM 渠道   运营：日志、标注、统计  │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>本质上，它们是把 <a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a> 里讲的两类应用，以产品化的方式交付：</p><ul><li><strong>Agent 模式</strong>：给定提示词、工具和知识库，由模型自主决定调用什么，对应 <a href="/guide/06-agent-loop/react">ReAct</a> 循环；</li><li><strong>工作流模式</strong>：在画布上拖出确定的步骤和分支，模型只是其中的节点，适合流程固定、需要稳定输出的业务。</li></ul><h2 id="dify-与-coze" tabindex="-1">Dify 与 Coze <a class="header-anchor" href="#dify-与-coze" aria-label="Permalink to &quot;Dify 与 Coze&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Dify</th><th>Coze（扣子）</th></tr></thead><tbody><tr><td>出品方</td><td>LangGenius（开源社区项目）</td><td>字节跳动</td></tr><tr><td>开源与部署</td><td>开源，可用 Docker 自部署，也有云服务</td><td>以云服务为主；2025 年开源了 Coze Studio 和 Coze Loop，可自部署</td></tr><tr><td>模型</td><td>支持大量厂商与本地模型（如通过 Ollama），自行配置 Key</td><td>云版深度集成豆包等模型；开源版可自行接入模型</td></tr><tr><td>核心能力</td><td>Chatflow、Workflow、Agent、知识库、插件、MCP</td><td>Agent（智能体）、工作流、知识库、插件、多渠道发布</td></tr><tr><td>发布渠道</td><td>Web 应用、API、嵌入网页</td><td>豆包、飞书、微信等渠道，以及 API / SDK</td></tr><tr><td>典型用户</td><td>需要私有化部署的企业、开发团队</td><td>面向个人与业务人员的快速搭建，和字节生态结合紧密</td></tr><tr><td>许可</td><td>基于 Apache 2.0 并附加条件（如多租户、商标方面的限制），商用前需阅读许可</td><td>开源部分采用 Apache 2.0；云服务按平台条款</td></tr></tbody></table><p>简单理解：<strong>数据要留在自己机房、需要深度定制，倾向 Dify；想快速做出能在飞书、豆包等渠道使用的 Bot，倾向 Coze</strong>。同类平台还有 n8n（偏通用自动化）、FastGPT（偏知识库问答）、阿里云百炼等，思路相近。</p><h2 id="典型用法" tabindex="-1">典型用法 <a class="header-anchor" href="#典型用法" aria-label="Permalink to &quot;典型用法&quot;">​</a></h2><h3 id="_1-快速验证想法" tabindex="-1">1. 快速验证想法 <a class="header-anchor" href="#_1-快速验证想法" aria-label="Permalink to &quot;1. 快速验证想法&quot;">​</a></h3><p>产品经理或业务专家可以在一个下午搭出&quot;上传产品手册 → 客服问答&quot;的原型，直接拿真实问题去测试。如果效果不行，问题往往在知识库质量或需求本身，而不是代码，这时候还没写一行代码，试错成本最低。</p><h3 id="_2-作为后端能力被业务系统调用" tabindex="-1">2. 作为后端能力被业务系统调用 <a class="header-anchor" href="#_2-作为后端能力被业务系统调用" aria-label="Permalink to &quot;2. 作为后端能力被业务系统调用&quot;">​</a></h3><p>Dify 和 Coze 发布的应用都可以通过 HTTP API 调用。常见架构是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  业务系统（Java / Go / Python）</span></span>
<span class="line"><span>        │  HTTP API（带 API Key）</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  低代码平台上的工作流 / Agent  ──▶ 知识库、模型、插件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>业务系统负责鉴权、用户体系和数据落库，平台负责&quot;AI 那一段&quot;。提示词和流程的调整由运营在平台上完成，不需要业务系统发版。</p><h3 id="_3-和代码混合使用" tabindex="-1">3. 和代码混合使用 <a class="header-anchor" href="#_3-和代码混合使用" aria-label="Permalink to &quot;3. 和代码混合使用&quot;">​</a></h3><ul><li>平台工作流中的 &quot;代码&quot; 节点可以写 Python / JavaScript 片段处理数据；</li><li>复杂的工具用代码实现成 HTTP API 或 <a href="/guide/10-mcp/mcp-server">MCP Server</a>，再注册为平台插件；</li><li>平台只负责编排与运营，核心逻辑留在你可测试、可版本管理的代码里。</li></ul><h2 id="低代码还是写代码" tabindex="-1">低代码还是写代码 <a class="header-anchor" href="#低代码还是写代码" aria-label="Permalink to &quot;低代码还是写代码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>考量</th><th>倾向低代码</th><th>倾向写代码</th></tr></thead><tbody><tr><td>需求阶段</td><td>探索期、需求不清楚</td><td>需求稳定、准备规模化</td></tr><tr><td>维护者</td><td>业务人员、运营参与调整</td><td>研发团队维护</td></tr><tr><td>流程复杂度</td><td>线性流程、少量分支</td><td>复杂状态、长时间运行、人工审批、多 Agent 协作</td></tr><tr><td>测试与发布</td><td>可接受平台内的手工测试</td><td>需要单元测试、<a href="/guide/14-evaluation/regression">回归测试</a>、代码评审、灰度发布</td></tr><tr><td>性能与成本</td><td>调用量不大</td><td>高并发、需要精细控制 Token 与延迟</td></tr><tr><td>集成深度</td><td>调几个 HTTP 接口</td><td>深度嵌入现有系统、复杂权限模型</td></tr></tbody></table><p>一个常见的演进路径：<strong>低代码搭原型 → 验证价值 → 把高频、复杂、对稳定性要求高的部分逐步迁移到代码</strong>，平台上保留运营频繁调整的部分。</p><h2 id="迁移时机的信号" tabindex="-1">迁移时机的信号 <a class="header-anchor" href="#迁移时机的信号" aria-label="Permalink to &quot;迁移时机的信号&quot;">​</a></h2><p>出现以下情况时，就该认真考虑迁移到代码框架：</p><ul><li>画布上的节点多到一屏放不下，没人能说清整个流程；</li><li>需要做版本对比、回滚和自动化评估，而平台的版本管理满足不了；</li><li>每次改动都担心影响其他场景，但没有办法做回归测试；</li><li>需要平台不支持的能力，例如精细的上下文管理（见 <a href="/guide/07-context-engineering/overview">什么是上下文工程</a>）、自定义的重试与降级；</li><li>调用量增长后，平台成本或性能成为瓶颈。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>把平台当成&quot;不需要懂原理&quot;</strong>：知识库效果差、Agent 乱调用工具时，排查方法和代码开发完全一样：看检索结果、看提示词、看工具描述。前面模块的知识在这里同样必要。</li><li><strong>API Key 暴露在前端</strong>：平台应用的 API Key 拥有调用权限和费用，应只在后端使用，不要写进网页或 App 代码。</li><li><strong>忽视数据合规</strong>：使用云服务时，上传的文档和对话数据存储在平台方。涉及客户数据、内部资料时，先确认合规要求，必要时选择私有化部署。</li><li><strong>没有评估集</strong>：在平台上改了提示词&quot;感觉更好了&quot;就发布，结果其他问题变差。准备一组固定的测试问题，每次改动后都跑一遍，参考 <a href="/guide/14-evaluation/eval-design">评估集与指标设计</a>。</li><li><strong>忽略许可证条款</strong>：开源不等于可以随意商用或改造成 SaaS 对外售卖，自部署商用前阅读对应版本的许可证。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>一家医疗机构希望基于内部诊疗规范做一个问答助手，数据不能出院区，Dify 和 Coze 云版应该选哪个？为什么？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>优先选择可私有化部署的方案，例如自部署 Dify（或自部署 Coze 开源版），并接入本地或私有云部署的模型，确保文档和对话数据不离开内网。Coze 云版的数据存储在平台方，不满足数据不出院区的要求。</p></details><ol start="2"><li>什么情况下应该把一个 Dify 工作流迁移为代码实现？列举至少两个信号。</li></ol><details class="details custom-block"><summary>查看答案</summary><p>例如：流程复杂到难以理解和维护；需要自动化回归测试、代码评审和灰度发布；需要平台不支持的能力（复杂状态、人工审批、自定义重试降级）；调用量增长后性能或成本成为瓶颈。</p></details><ol start="3"><li>为什么说&quot;低代码平台 + 自研 MCP Server / HTTP API&quot;是一种不错的混合方案？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>核心业务逻辑和对外系统的访问写成代码，可以测试、做权限控制和版本管理；平台只负责编排和提示词，运营可以灵活调整。两者各取所长，以后迁移到代码框架时，工具部分也能直接复用。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://github.com/langgenius/dify" target="_blank" rel="noreferrer">Dify GitHub 仓库</a></li><li><a href="https://github.com/coze-dev/coze-studio" target="_blank" rel="noreferrer">Coze Studio GitHub 仓库</a></li><li><a href="https://github.com/n8n-io/n8n" target="_blank" rel="noreferrer">n8n GitHub 仓库</a></li><li>相关：<a href="/guide/11-frameworks/overview">框架全景与选型</a>、<a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></li></ul>`,37)])])}const b=t(l,[["render",i]]);export{h as __pageData,b as default};
